let audio=null,engine=null,engineGain=null,muted=false;
function audioStart(){if(muted)return;try{if(!audio){audio=new (window.AudioContext||window.webkitAudioContext)();engine=audio.createOscillator();engineGain=audio.createGain();engine.type='triangle';engineGain.gain.value=0;engine.connect(engineGain);engineGain.connect(audio.destination);engine.start()}if(audio.state==='suspended')audio.resume().catch(()=>{})}catch{}}
function tone(freq,duration=.12,type='sine',volume=.05,delay=0,end=freq){if(!audio||muted)return;const at=audio.currentTime+delay,o=audio.createOscillator(),g=audio.createGain();o.type=type;o.frequency.setValueAtTime(freq,at);o.frequency.exponentialRampToValueAtTime(Math.max(1,end),at+duration);g.gain.setValueAtTime(.001,at);g.gain.linearRampToValueAtTime(volume,at+.015);g.gain.exponentialRampToValueAtTime(.001,at+duration);o.connect(g);g.connect(audio.destination);o.start(at);o.stop(at+duration+.03)}
function sound(kind){audioStart();if(kind==='door'){tone(170,.14,'triangle',.05,0,90);tone(270,.12,'sine',.025,.1)}else if(kind==='board'){tone(90,.16,'triangle',.05,0,180)}else if(kind==='bell'){tone(880,.45,'sine',.055);tone(1320,.3,'sine',.025,.05)}else if(kind==='talk'){tone(440,.09);tone(550,.12,'sine',.04,.1)}else if(kind==='success'){[523,659,784,1047].forEach((f,i)=>tone(f,.25,'sine',.055,i*.12))}else if(kind==='subway'){tone(660,.3);tone(520,.3,'sine',.04,.35)}else if(kind==='step')tone(90,.045,'triangle',.022,0,45);else if(kind==='horn'){if(vehicle?.type==='bicycle'||vehicle?.type==='scooter')sound('bell');else{tone(vehicle?.type==='boat'?130:220,.3,'sawtooth',.022);tone(vehicle?.type==='boat'?195:280,.3,'sine',.04)}}}
function audioUpdate(){if(!engineGain)return;const running=!muted&&!modalOpen()&&document.visibilityState!=='hidden';let gain=0,freq=60;if(running&&vehicle&&vehicle.type!=='bicycle'){const r=vehicle.speed/350;gain=.015+r*.025;freq=(vehicle.type==='boat'?45:vehicle.type==='train'?55:vehicle.type==='bus'?55:['motorcycle','police motorcycle'].includes(vehicle.type)?125:vehicle.type==='scooter'?110:70)+r*85+Math.sin(time*25)*3}if(running&&travel){gain=.03;freq=65+Math.sin(travel.elapsed/travel.duration*Math.PI)*65}engineGain.gain.setTargetAtTime(gain,audio.currentTime,.12);engine.frequency.setTargetAtTime(freq,audio.currentTime,.12)}
