function circle(x,y,r,fill){c.beginPath();c.ellipse(x,y,r,r*1.06,.1,0,Math.PI*2);if(fill){c.fillStyle=fill;c.fill()}c.strokeStyle='#53564c';c.lineWidth=2;c.stroke()}
