function targetMarker(t,label,blue=false){if(!t)return;const rise=reduced.matches?0:Math.sin(time*3)*4;text('↓',t.x,t.y-55+rise,blue?42:30,blue?'#267cb6':'#a46d3e');circle(t.x,t.y,blue?34:28,blue?'#75bae455':'#e4cb7a33');if(map)text(label||'GO HERE',t.x,t.y-80,24,blue?'#267cb6':'#986236')}
const policeChases=[{officer:{x:700,y:540},robber:{x:1120,y:540},waypoint:0,caught:0,phase:0},{officer:{x:1650,y:1830},robber:{x:2130,y:1830},waypoint:2,caught:0,phase:0}];
const chaseLoop=[[665,540],[2265,540],[2265,1830],[665,1830]];
const patrolRoutes=new Map();
function updatePoliceCars(dt){
for(const car of cars.filter(v=>['police car','police motorcycle'].includes(v.type)&&!v.room&&!v.id)){
if(vehicle===car){const previous=patrolRoutes.get(car);if(previous?.prisoner){previous.prisoner.transport=null;previous.prisoner.caught=18}patrolRoutes.delete(car);continue}
let patrol=patrolRoutes.get(car);if(!patrol){patrol={route:[],target:null,prisoner:null,replan:0};patrolRoutes.set(car,patrol)}
if(!patrol.prisoner){patrol.replan-=dt;if(patrol.replan<=0){patrol.target=policeChases.filter(ch=>(!ch.caught||ch.awaitingPickup)&&!ch.transport&&!ch.jailed).sort((a,b)=>Math.hypot(a.robber.x-car.x,a.robber.y-car.y)-Math.hypot(b.robber.x-car.x,b.robber.y-car.y))[0];patrol.route=patrol.target?busRoadRoute(car,patrol.target.robber)||[]:busRoadRoute(car,{x:1320,y:1120})||[];patrol.replan=.8}
if(patrol.target&&(!patrol.target.caught||patrol.target.awaitingPickup)&&Math.hypot(car.x-patrol.target.robber.x,car.y-patrol.target.robber.y)<75){const ch=patrol.target;ch.caught=999;ch.awaitingPickup=false;ch.transport=car;patrol.prisoner=ch;patrol.route=busRoadRoute(car,{x:1320,y:1120})||[];notify('Police caught a robber! Taking them to the station.');sound('bell')}
}
const next=patrol.route[0];if(next){const dx=next.x-car.x,dy=next.y-car.y,d=Math.hypot(dx,dy);if(d<2)patrol.route.shift();else{const step=Math.min(d,150*dt);car.x+=dx/d*step;car.y+=dy/d*step;car.speed=150;car.phase+=step*.1;if(dx)car.face=dx>0?1:-1}}else{car.speed=0;if(patrol.prisoner){const ch=patrol.prisoner;ch.transport=null;ch.jailed=true;ch.caught=60;patrol.prisoner=null;patrol.target=null;notify('The robber is in a Police station jail cell.');sound('bell')}}
if(patrol.prisoner){patrol.prisoner.robber.x=car.x;patrol.prisoner.robber.y=car.y}
}}

function updatePolice(dt){for(const chase of policeChases){chase.phase+=dt*8;if(chase.transport||chase.awaitingPickup)continue;if(chase.caught>0){chase.caught-=dt;if(chase.caught<=0){chase.jailed=false;chase.waypoint=(chase.waypoint+1)%chaseLoop.length;chase.robber.x=chaseLoop[chase.waypoint][0];chase.robber.y=chaseLoop[chase.waypoint][1];chase.waypoint=(chase.waypoint+1)%chaseLoop.length}continue}const r=chase.robber,o=chase.officer,target=chaseLoop[chase.waypoint];let dx=target[0]-r.x,dy=target[1]-r.y,d=Math.hypot(dx,dy);if(d<5)chase.waypoint=(chase.waypoint+1)%chaseLoop.length;else{r.x+=dx/d*Math.min(d,62*dt);r.y+=dy/d*Math.min(d,62*dt)}dx=r.x-o.x;dy=r.y-o.y;d=Math.hypot(dx,dy);if(d<22){chase.caught=18;if(scene==='city'&&Math.hypot(p.x-o.x,p.y-o.y)<600){notify('The police caught a robber! The city is safe.');sound('bell')}}else{const step=Math.min(d,92*dt);if(!blocked(o.x+dx/d*step,o.y,14))o.x+=dx/d*step;if(!blocked(o.x,o.y+dy/d*step,14))o.y+=dy/d*step}}}
function drawPolice(){for(const chase of policeChases){if(chase.transport||chase.jailed)continue;const o=chase.officer,r=chase.robber;person(o.x,o.y,chase.phase,!chase.caught,'#6992bd');rect(o.x-9,o.y-35,18,5,'#57778f');rect(o.x-6,o.y-41,12,6,'#57778f');text('★',o.x+3,o.y-5,9,'#d5ad44');rect(o.x+7,o.y-1,7,10,'#77705c');line([[o.x+8,o.y-3],[o.x+15,o.y-3],[o.x+15,o.y],[o.x+11,o.y],[o.x+11,o.y+5]],'#53564c',3);person(r.x,r.y,chase.phase,!chase.caught,'#b9b9ab');line([[r.x-7,r.y-25],[r.x+7,r.y-25]],'#53564c',3);for(let yy=-10;yy<3;yy+=4)line([[r.x-5,r.y+yy],[r.x+5,r.y+yy]],'#53564c',1);text(chase.caught?'Caught!':'Robber',r.x,r.y-46,13);text('Police',o.x,o.y-48,13);if(chase.caught){line([[o.x+12,o.y-2],[r.x-12,r.y-2]],'#77796a',1)}}}
const cityLetters=[];
function sendCityLetter(destination){cityLetters.push({from:door('Post office'),to:door(destination),name:destination,elapsed:0});notify('Your letter is on its way to '+destination+'!');sound('bell')}
function updateCityLetters(dt){for(let j=cityLetters.length-1;j>=0;j--){const letter=cityLetters[j];letter.elapsed+=dt;if(letter.elapsed>=5){notify('Your letter arrived at '+letter.name+'!');sound('bell');cityLetters.splice(j,1)}}}
function drawCityLetters(){for(const letter of cityLetters){const t=letter.elapsed/5,x=letter.from.x+(letter.to.x-letter.from.x)*t,y=letter.from.y+(letter.to.y-letter.from.y)*t-Math.sin(t*Math.PI)*80;rect(x-13,y-9,26,18,'#f8f2df');line([[x-13,y-9],[x,y+2],[x+13,y-9]],'#77796a',1)}}
let deliveryJob={wait:0,stage:'ready',number:1};try{const saved=JSON.parse(localStorage.getItem('around-city-delivery'));if(saved)deliveryJob=saved}catch{}
function saveDelivery(){try{localStorage.setItem('around-city-delivery',JSON.stringify(deliveryJob))}catch{}}
function updateDelivery(dt){if(deliveryJob.stage==='waiting'){deliveryJob.wait-=dt;if(deliveryJob.wait<=0){deliveryJob.stage='ready';deliveryJob.number++;saveDelivery();notify('New delivery job! Collect a package at the Post office.');sound('bell')}}$('#delivery-job').textContent=deliveryJob.stage==='waiting'?'📦 Next job: '+Math.ceil(deliveryJob.wait/60)+' min':deliveryJob.stage==='carrying'?'📦 Deliver to house':'📦 Package job';}
function guideDelivery(){shopDestination=deliveryJob.stage==='carrying'?'Delivery house':'Post office';$('#shop-select').value=shopDestination;try{localStorage.setItem('around-city-destination',shopDestination)}catch{}if(deliveryJob.stage==='waiting')notify('The next delivery job arrives in '+Math.ceil(deliveryJob.wait/60)+' minutes.');else notify(deliveryJob.stage==='carrying'?'Follow the arrow to the house and press E at the door.':'Pick up your package at the Post office door with E.');updateUI()}
function deliveryInteraction(){if(scene!=='city'||deliveryJob.stage==='waiting')return null;const name=deliveryJob.stage==='carrying'?'Delivery house':'Post office',point=door(name);if(Math.hypot(point.x-p.x,point.y-p.y)<85)return {kind:'delivery',label:deliveryJob.stage==='carrying'?'Deliver package':'Pick up delivery package'};return null}
function doDelivery(){if(deliveryJob.stage==='ready'){deliveryJob.stage='carrying';shopDestination='Delivery house';notify('Package picked up! Take it to the house.')}else if(deliveryJob.stage==='carrying'){deliveryJob.stage='waiting';deliveryJob.wait=600;activityState.coins+=10;saveActivities();notify('Delivered! You earned 10 play coins. Another job in ten minutes.');sound('success')}saveDelivery();updateUI()}
const themeRides=[{x:245,y:360,name:'Ferris wheel'},{x:465,y:350,name:'Carousel'},{x:650,y:370,name:'Roller coaster'}];let themeParkRide=null;
