function drawGolfCourse(){rect(130,130,800,420,'#b7d3a4');for(const [x,y] of [[350,250],[690,320],[180,190]]){circle(x,y,28,'#e5d2a2')}line([[430,525],[430,485],[880,485],[880,190],[190,190],[190,485],[430,485]],'#d8c9a7',34);line([[190,365],[880,365]],'#d8c9a7',30);line([[430,485],[430,365],[570,365],[570,190]],'#d8c9a7',30);line([[430,525],[430,485],[880,485],[880,190],[190,190],[190,485],[430,485]],'#f5efdb',2);text('CART PATH',700,505,14);for(let i=0;i<golfHoles.length;i++){const h=golfHoles[i];circle(h.hx,h.hy,48,'#91ba7d');circle(h.hx,h.hy,7,'#53564c');line([[h.hx,h.hy],[h.hx,h.hy-60]],'#53564c',3);line([[h.hx,h.hy-60],[h.hx+25,h.hy-50],[h.hx,h.hy-40]],'#c77755',4);text(String(i+1),h.hx+12,h.hy-65,18)}for(let i=0;i<(twoPlayers?2:1);i++){const r=golfRounds[i],h=golfHoles[r.hole];if(!r.done)circle(h.x+(h.hx-h.x)*r.roll,h.y+(h.hy-h.y)*r.roll,8,i?'#a6cde1':'#fff8ed')}for(const v of cars.filter(v=>v.room==='Golf course'))drawCar(v);text('Hop out · walk to your ball · E / F to putt',430,175,16)}
function puttGolf(){const r=golfRounds[secondTurn?1:0];if(r.done){r.done=false;r.hole=0;r.roll=0;return}if(!r.roll){r.roll=.001;sound('bell');notify('Nice putt!')}}
function updateGolfCourse(dt){const r=golfRounds[secondTurn?1:0];if(!r.roll||r.done)return;r.roll=Math.min(1,r.roll+dt*.65);if(r.roll===1){r.roll=0;r.hole++;if(r.hole===golfHoles.length){r.hole=golfHoles.length-1;r.done=true;notify('All six holes finished! Great golfing!');sound('success')}else notify('In the hole! Walk to the next ball.')}}
function visitGolfArea(name){currentBuilding=buildings.find(b=>b.name===name);scene='inside';p.x=430;p.y=480;if(vehicle){vehicle.room=name;vehicle.x=p.x;vehicle.y=p.y}activityRoom='';updateUI();sound('door')}

