function updateBumperCars(dt){if(scene!=='inside'||currentBuilding.name!=='Bumper cars')return;if(!secondTurn){const npc=bumperCars[2];npc.x+=npc.vx*dt;npc.y+=npc.vy*dt;if(npc.x<210||npc.x>650)npc.vx*=-1;if(npc.y<210||npc.y>410)npc.vy*=-1;npc.x=Math.max(210,Math.min(650,npc.x));npc.y=Math.max(210,Math.min(410,npc.y));npc.phase+=dt*6}if(vehicle?.type==='bumper car'){vehicle.bumpCooldown=Math.max(0,(vehicle.bumpCooldown||0)-dt);for(const other of bumperCars){if(other===vehicle)continue;let dx=p.x-other.x,dy=p.y-other.y,d=Math.hypot(dx,dy);if(d<60){if(!vehicle.bumpCooldown){activityState.coins++;saveActivities();vehicle.bumpCooldown=.8;notify('Bump! +1 play coin');}if(d<1){dx=1;dy=0;d=1}p.x=Math.max(210,Math.min(650,other.x+dx/d*60));p.y=Math.max(210,Math.min(410,other.y+dy/d*60));vehicle.x=p.x;vehicle.y=p.y;vehicle.speed*=.3;flash=.12;if(other.computer){other.vx*=-1;other.vy*=-1}sound('bell')}}}}
