function horseTrackPoint(t){const a=t*Math.PI*2;return {x:530+285*Math.cos(a),y:350+100*Math.sin(a)}}
let horseAnnouncerOn=false,horseAnnouncementTimer=0,lastHorseLeader=null;
const horseSpeeds=['Medium','Medium'];let selectedRacer=4;
function chooseRacer(number){selectedRacer=number;notify('Controlling horse '+number);activityRoom='';updateUI()}
function setSelectedRacerSpeed(speed){if(selectedRacer<=3)setOtherHorseSpeed(selectedRacer,speed);else setHorseSpeed(speed)}
function setHorseSpeed(speed){horseSpeeds[secondTurn?1:0]=speed;notify('Horse speed: '+speed);sound('bell')}
function horsePlayerProgress(number){const currentNumber=secondTurn?5:4;const other=twoPlayers?(secondTurn?playerOneView:playerTwo):null;const ride=number===currentNumber?themeParkRide:other?.themeParkRide;return (ride?.distance??horseRaceClock*.12)+.06*Math.sin(horseRaceClock*.7+(number===4?Math.PI/3:Math.PI))}
const otherHorseSpeeds=['Medium','Medium','Medium'],otherHorseOffsets=[0,0,0];
function setOtherHorseSpeed(number,speed){otherHorseSpeeds[number-1]=speed;notify('Horse '+number+': '+speed);sound('bell')}
function horseRaceProgress(i){return horseRaceClock*.12+otherHorseOffsets[i]+.05*Math.sin(horseRaceClock*.7+i*Math.PI*2/3)}
function horseStandings(){const racers=[1,2,3].map((number,i)=>({number,progress:horseRaceProgress(i)}));if(themeParkRide?.name==='Horse race')racers.push({number:secondTurn?5:4,progress:horsePlayerProgress(secondTurn?5:4)});const other=twoPlayers?(secondTurn?playerOneView:playerTwo):null;if(other?.currentBuilding?.name==='Horse racing fair'&&other.themeParkRide?.name==='Horse race')racers.push({number:secondTurn?4:5,progress:horsePlayerProgress(secondTurn?4:5)});return racers.sort((a,b)=>b.progress-a.progress||a.number-b.number)}
function horseAnnouncement(){const leaders=horseStandings();return (lastHorseLeader===null?'Horse number ':'Now horse number ')+leaders[0].number+' is in first place!'}
function speakHorseAnnouncer(){const leader=horseStandings()[0].number;if(leader===lastHorseLeader)return;const message=horseAnnouncement();lastHorseLeader=leader;notify('Announcer: '+message);if(!muted&&typeof speechSynthesis!=='undefined'&&typeof SpeechSynthesisUtterance!=='undefined'){speechSynthesis.cancel();const words=new SpeechSynthesisUtterance(message);words.rate=.85;speechSynthesis.speak(words)}}
function toggleHorseAnnouncer(){horseAnnouncerOn=!horseAnnouncerOn;horseAnnouncementTimer=2;lastHorseLeader=null;if(horseAnnouncerOn)speakHorseAnnouncer();else if(typeof speechSynthesis!=='undefined')speechSynthesis.cancel();activityRoom='';updateUI()}
