function updateThemeRide(dt){if(!themeParkRide)return false;themeParkRide.elapsed+=dt;if(themeParkRide.name==='Hayride'){if(themeParkRide.elapsed>=20){themeParkRide=null;notify('Back at the welcome house!');updateUI()}return true}if(themeParkRide.name==='Horse race'){themeParkRide.distance=(themeParkRide.distance||0)+dt*({'Slow':.06,'Medium':.12,'Super Fast':.24}[horseSpeeds[secondTurn?1:0]]);const round=Math.floor(themeParkRide.elapsed/6);if(round>(themeParkRide.round||0)){themeParkRide.round=round;horseGateOpen=8;sound('bell');notify('Two more laps finished! Keep riding, or press '+(secondTurn?'F':'E')+' to get off.')}audioUpdate();return true}if(themeParkRide.name==='Airport shuttle'){if(themeParkRide.elapsed>=2){visitParkArea('Airport terminal');notify('At the terminal! Choose a place to fly.')}return true}if(themeParkRide.name==='Airplane flight'){if(themeParkRide.elapsed>=8){const destination=themeParkRide.destination;if(['Arcade','Pool'].includes(destination))shopDestination=destination;themeParkRide=null;vehicle=null;scene='city';Object.assign(p,destinationPoint(destination));p.y+=60;sound('bell');notify('Your plane landed near '+destination+'!');updateUI()}return true}if(themeParkRide.name==='Horse shuttle'){p.x=Math.min(665,p.x+dt*75);vehicle.x=p.x;vehicle.y=p.y;vehicle.phase+=dt*8;if(themeParkRide.elapsed>=6){const cart=themeParkRide.cart;cart.x=secondTurn?420:260;cart.y=345;visitParkArea('Horse racing fair');sound('bell');notify('Welcome to the horse stadium!')}return true;}if(themeParkRide.elapsed>=8){if(themeParkRide.name==='Horse race'){horseGateOpen=8;horseRaceClock=0}themeParkRide=null;sound('bell');notify('Ride finished! Try another one.');updateUI()}audioUpdate();return true}
