function startDerby(race=false){$('#derby-choice').close();if(vehicle&&!['motorcycle','police motorcycle'].includes(vehicle.type)){notify('Hop out first to ride a derby motorcycle.');return}if(!vehicle){let bike=cars.find(v=>v.derby&&v.derbyPlayer===(secondTurn?2:1));if(!bike){bike={x:300,y:2010,type:'motorcycle',color:'#c48c73',derby:true,derbyPlayer:secondTurn?2:1,speed:0,phase:0,face:1};cars.push(bike)}vehicle=bike}p.x=vehicle.x=300;p.y=vehicle.y=2010;derbyRace={elapsed:0,checkpoint:0,rival:race?{x:300,y:2020,type:'motorcycle',color:'#b5c9de',speed:150,phase:0,face:-1,index:0,finished:false}:null};sound('bell');notify('Motorcycle derby! Follow the gold rings around the track.');updateUI()}
function drawDerby(){for(const y of [1840,2060]){rect(90,y,780,30,'#c7b493');for(let row=0;row<3;row++)line([[90,y+row*10],[870,y+row*10]],'#77796a',2);for(let x=100;x<870;x+=90)line([[x,y+30],[x,y+37]],'#77796a',2)}line([[90,1810],[90,1850]],'#77796a',3);line([[870,1810],[870,1850]],'#77796a',3);line([[90,1810],[300,1820],[650,1820],[870,1810]],'#77796a',2);for(let x=120;x<850;x+=55){line([[x,1818],[x,1830]],'#77796a',1);circle(x,1833,5,'#f4df8b')}for(let j=0;j<14;j++){const x=100+j*55,y=j%2?1850:2070;person(x,y,j*.7,false,['#e3b6cc','#b5c9de','#c9d0ac','#e9c6ac'][j%4],!!derbyRace)}rect(80,1865,800,190,'#d6dfbc');rect(115,1885,730,145,'#d2c8ad');rect(170,1940,620,45,'#d6dfbc');line([[115,2015],[115,1885],[845,1885],[845,2030],[115,2030]],'#f8f2df',3);for(const ramp of derbyRamps){c.fillStyle='#c8a87c';c.beginPath();c.moveTo(ramp.x-22,ramp.y+14);c.lineTo(ramp.x+22,ramp.y-8);c.lineTo(ramp.x+22,ramp.y+14);c.closePath();c.fill();c.stroke();line([[ramp.x-22,ramp.y+14],[ramp.x+22,ramp.y-8]],'#77796a',3);text('JUMP',ramp.x,ramp.y-20,11)}text('MOTORCYCLE DERBY',480,1877,18);text('START / FINISH',300,2048,14);for(let j=0;j<derbyPoints.length;j++){const [x,y]=derbyPoints[j];circle(x,y,16,derbyRace?.checkpoint===j?'#efcf70':'#f8f2df');text(String(j+1),x,y+5,13)}if(derbyRace?.rival){drawCar(derbyRace.rival);person(derbyRace.rival.x,derbyRace.rival.y-10,0,false,'#c9d0ac');text('Racer',derbyRace.rival.x,derbyRace.rival.y-55,13)}if(derbyRace)text('Ring '+(derbyRace.checkpoint+1)+'/4 · '+derbyRace.elapsed.toFixed(1)+' sec',480,1968,17)}
function updateDerby(dt){if(vehicle&&['motorcycle','police motorcycle'].includes(vehicle.type)){vehicle.jump=Math.max(0,(vehicle.jump||0)-dt);vehicle.jumpCooldown=Math.max(0,(vehicle.jumpCooldown||0)-dt);if(!vehicle.jumpCooldown&&vehicle.speed>50&&derbyRamps.some(r=>Math.hypot(r.x-p.x,r.y-p.y)<25)){vehicle.jump=.9;vehicle.jumpCooldown=1.5;sound('bell');notify('Wheee! Motorcycle jump!')}}if(!derbyRace)return;if(!vehicle||!['motorcycle','police motorcycle'].includes(vehicle.type)){derbyRace=null;return}derbyRace.elapsed+=dt;const rival=derbyRace.rival;if(rival&&!rival.finished){const [rx,ry]=derbyPoints[rival.index],dx=rx-rival.x,dy=ry-rival.y,d=Math.hypot(dx,dy);if(d<4){rival.index++;if(rival.index===4){rival.finished=true;notify('The other rider finished! Keep going to finish your lap.')}}else{const step=Math.min(d,150*dt);rival.x+=dx/d*step;rival.y+=dy/d*step;rival.phase+=step*.1;if(dx)rival.face=dx>0?1:-1}}const [x,y]=derbyPoints[derbyRace.checkpoint];if(Math.hypot(p.x-x,p.y-y)<35){derbyRace.checkpoint++;sound('bell');if(derbyRace.checkpoint===4){notify((derbyRace.rival?(derbyRace.rival.finished?'You finished second! ':'You won the race! '):'Derby complete! ')+'Your time: '+derbyRace.elapsed.toFixed(1)+' seconds.');sound('success');derbyRace=null}}}
