function askBoatCaptain(){if(boatJourney){boatJourney=null;if(vehicle)vehicle.speed=0;notify('Captain stopped. You can steer again.');updateUI();return}if(vehicle?.type!=='boat'||scene!=='city')return;const from=docks.reduce((best,d)=>Math.hypot(d.x+140-p.x,d.y-p.y)<Math.hypot(best.x+140-p.x,best.y-p.y)?d:best,docks[0]);const to=docks.find(d=>d!==from);boatJourney={to};sound('board');notify('Captain: Sailing to '+to.name+'!');updateUI()}
function updateBoatJourney(dt){if(!boatJourney)return false;if(vehicle?.type!=='boat'||scene!=='city'){boatJourney=null;return false}const dock=boatJourney.to,dx=dock.x+140-p.x,dy=dock.y-p.y,d=Math.hypot(dx,dy);if(d<3){p.x=vehicle.x=dock.x+140;p.y=vehicle.y=dock.y;vehicle.dock=docks.indexOf(dock);vehicle.speed=0;boatJourney=null;if(vehicle.id)saveOwnedCars();sound('bell');notify('Captain: Arrived at '+dock.name+'! Press E to get out.');updateUI()}else{const step=Math.min(d,170*dt);p.x+=dx/d*step;p.y+=dy/d*step;vehicle.x=p.x;vehicle.y=p.y;vehicle.speed=170;vehicle.phase+=step*.1;if(dx)vehicle.face=dx>0?1:-1}audioUpdate();return true}
