const listener=new Recognition();destinationListener=listener;listener.lang='en-US';listener.interimResults=false;listener.maxAlternatives=1;$('#speak-destination').textContent='🎤 Listening…';
listener.onresult=e=>{const words=e.results[0][0].transcript.toLowerCase();const places=[['south dock','South dock'],['market dock','Market dock'],['touch a truck','Touch a Truck'],['truck touch','Touch a Truck'],['airport station','Airport station'],['airport','Airport'],['plane','Airport'],['horse','Horse racing fair'],['golf cart','Golf cart track'],['golf','Golf course'],['pool','Pool'],['arcade','Arcade'],['trampoline','Trampoline park'],['theme park','Theme park'],['post office','Post office'],['delivery house','Delivery house'],['derby','Motorcycle derby'],['race','Motorcycle derby'],['playground','Playground'],['park','Playground'],['robber','Find a robber'],['bad guy','Find a robber'],['police','Police station'],['train station','Market station'],['subway','Market station'],['market station','Market station'],['park station','Park station'],['river station','River station'],['toy town station','Toy town station'],['starlight station','Starlight station'],['boat','Market dock'],['dock','Market dock'],['bank','Bank'],['toy','Toy shop'],['flower','Flower shop'],['music','Music shop'],['bakery','Bakery'],['bread','Bakery'],['bookshop','Bookshop'],['book shop','Bookshop'],['library','Library'],['museum','Museum'],['art','Art studio'],['garage','Garage'],['car','Car store'],['cafe','Café'],['coffee','Café']];const found=places.find(([word])=>words.includes(word));if(found)setSpokenDestination(found[1]);else{notify('Try saying Bank, Toy shop, Library, or Car store.');$('#voice-destinations').hidden=false}};
